function b64ToBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

let cached = null;

export function sigilBytes() {
  if (!cached) cached = b64ToBytes(SIGIL_B64);
  return cached;
}

export function isSigilPath(pathname) {
  const path = String(pathname || "");
  return path === SIGIL_PATH || path === SIGIL_PATH + "/";
}

export function sigilResponse(pathname, extraHeaders) {
  if (!isSigilPath(pathname)) return null;
  return new Response(sigilBytes(), {
    status: 200,
    headers: {
      "content-type": "image/png",
      "cache-control": SIGIL_CACHE,
      "X-Content-Type-Options": "nosniff",
      "X-Aziel-Brandmark": "rose-star",
      ...(extraHeaders || {}),
    },
  });
}
